import{_ as s,o as a,c as t,a6 as e,j as n}from"./chunks/framework.BJFjZBwW.js";const o="/dev/assets/OpenMQTTGateway_LORA_Configuration.BtMmHla8.png",h="/dev/assets/OpenMQTTgateway_ESP32_LORA_MSG.DRwDOQLT.png",l="/dev/assets/OpenMQTTGateway_TTGO32_LORA_Receive.D7cd4Zx3.jpg",y=JSON.parse('{"title":"LoRa gateway","description":"Explore the LoRa MQTT gateway, designed for integration with devices utilizing LoRa technology, including the MakerFab soil and moisture sensor, devices from PricelessTookit. Unlock long range communication with the power of LoRa..","frontmatter":{"title":"LoRa gateway","description":"Explore the LoRa MQTT gateway, designed for integration with devices utilizing LoRa technology, including the MakerFab soil and moisture sensor, devices from PricelessTookit. Unlock long range communication with the power of LoRa.."},"headers":[],"relativePath":"use/lora.md","filePath":"use/lora.md","lastUpdated":1701025638000}'),r={name:"use/lora.md"};function p(k,i,d,E,g,u){return a(),t("div",null,[...i[0]||(i[0]=[e('<h1 id="lora-gateway" tabindex="-1">LoRa gateway <a class="header-anchor" href="#lora-gateway" aria-label="Permalink to &quot;LoRa gateway&quot;">​</a></h1><h2 id="what-is-a-lora-gateway" tabindex="-1">What is a LoRa gateway <a class="header-anchor" href="#what-is-a-lora-gateway" aria-label="Permalink to &quot;What is a LoRa gateway&quot;">​</a></h2><p>A LoRa (Long Range) gateway is a device that facilitates communication between LoRa nodes and networks, enabling the transmission and reception of data over long distances using the LoRa modulation technique. It&#39;s designed to work with devices that utilize LoRa technology, such as the MakerFab soil and moisture sensor, devices from PricelessTookit and DIY sensors.</p><p>The primary distinction between a LoRa gateway and a LoRaWAN gateway lies in the protocol and network architecture:</p><p>LoRa gateway: Focuses solely on the physical layer, utilizing the LoRa modulation for communication. It&#39;s responsible for receiving and transmitting raw LoRa signals without concerning itself with network protocols or data handling at higher layers. Being focused solely on the physical layer, a LoRa gateway offers greater flexibility for customization and experimentation. The OpenMQTTGateway LoRa gateway receives raw LoRa signals, processes them, and publishes the data to an MQTT topic. Conversely, it can subscribe to MQTT topics and send commands to LoRa devices. This gateway is particularly useful for DIY projects, home automation enthusiasts, and scenarios where direct integration of LoRa devices with MQTT is desired.</p><p>LoRaWAN gateway: Operates at a higher layer and is part of the LoRaWAN network architecture. LoRaWAN is a protocol specification built on top of the LoRa technology, providing features like adaptive data rate, encryption, and multi-channel/multi-modulation. A LoRaWAN gateway handles the data from multiple LoRa nodes, forwards it to a centralized network server, which then manages the data and communicates back to the nodes.</p><p>In essence, while both gateways utilize LoRa technology for communication, a LoRaWAN gateway is more sophisticated, offering advanced features and integration with the LoRaWAN network infrastructure. The LoRa gateway, with its simpler architecture, is ideal for small networks of nodes, offering easier setup and configuration, making it an interesting choice for users keen on experimenting with LoRa technology.</p><h2 id="configuring-the-lora-gateway" tabindex="-1">Configuring the LoRa gateway <a class="header-anchor" href="#configuring-the-lora-gateway" aria-label="Permalink to &quot;Configuring the LoRa gateway&quot;">​</a></h2><p>The LoRa gateway can be configured by MQTT commands or by using the WebUI, here are the parameters available, they can be combined with the key &quot;save&quot; or &quot;erase&quot;:</p><ul><li>txpower: 0 to 14</li><li>spreadingfactor: 7 to 12</li><li>frequency: 433000000, 868000000, 915000000</li><li>signalbandwidth: 7800, 10400, 15500, 20800, 31250, 41700, 62500, 125000, and 250000</li><li>codingrate: 5 to 8</li><li>preamblelength: 6 to 65535</li><li>syncword: byte</li><li>enablecrc: boolean</li><li>invertiq: boolean</li><li>onlyknown: boolean</li></ul><p>With the WebUI: <img src="'+o+`" alt="LoRa configuration page"></p><p>With MQTT commands: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoLORA/config -m &#39;{&quot;frequency&quot;:&quot;433000000&quot;,&quot;save&quot;:true}&#39;</code></p><h2 id="receiving-data-from-lora-signal" tabindex="-1">Receiving data from LoRa signal <a class="header-anchor" href="#receiving-data-from-lora-signal" aria-label="Permalink to &quot;Receiving data from LoRa signal&quot;">​</a></h2><p>Subscribe to all the messages with mosquitto or open your MQTT client software:</p><p><code> sudo mosquitto_sub -t +/# -v</code></p><p>Generate your LoRa signals by using another LoRa module, you can flash the sender program from <a href="./../../examples/LoraTemperature/">this example</a> to an ESP32 LoRa board, this sample node will generate a LoRa signal containing the ESP32 internal temperature.</p><p>Once one board flashed with OMG and the other with the sender program you should receive regular packets into <code>home/OpenMQTTGateway_ESP32_LORA_TEST/LORAtoMQTT/AABBCCDDEEFF</code> like below:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AA:BB:CC:DD:EE:FF&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rssi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pferror&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-3598</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;packetSize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tempc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;55.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AA:BB:CC:DD:EE:FF&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rssi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-26</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pferror&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-3598</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;packetSize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tempc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;55.4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AA:BB:CC:DD:EE:FF&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rssi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pferror&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-3581</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;packetSize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tempc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;57&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><img src="`+h+'" alt="LoRa board receiving data"></p><p>Messages that contain non-printable characters will be converted to hexadecimal and look like this:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rssi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-121</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-11.75</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pferror&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-29116</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;packetSize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C0FFEE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>They can be filtered by setting the &quot;onlyknown&quot; command to <code>true</code> or by an activation into the WebUI or Home Assistant.</p><p>And from a supported device (in this case, a WiPhone), looks like this:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rssi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pferror&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20728</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;packetSize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;from&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123ABC&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;to&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hi from WiPhone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WiPhone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="send-data-by-mqtt-to-convert-it-on-lora-signal" tabindex="-1">Send data by MQTT to convert it on LoRa signal <a class="header-anchor" href="#send-data-by-mqtt-to-convert-it-on-lora-signal" aria-label="Permalink to &quot;Send data by MQTT to convert it on LoRa signal&quot;">​</a></h2><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoLORA -m &#39;{&quot;message&quot;:&quot;hello OMG1&quot;}&#39;</code></p><p>This command will send by LoRa the message &quot;hello OMG1&quot; and use the default parameters defined in <a href="https://github.com/1technophile/OpenMQTTGateway/blob/4b8d28179b63ae3f3d454da57ec8c109c159c386/config_LORA.h#L32" target="_blank" rel="noreferrer">config_LORA.h</a></p><p><img src="'+l+'" alt="TTGO Lora receiving packets"></p><p>If you want to test that your sending works you can use another TTGO LoRa module, you can flash the receiver program from <a href="https://github.com/LilyGO/TTGO-LORA32-V2.0" target="_blank" rel="noreferrer">this repository</a> and the SSD1306 library <a href="https://github.com/ThingPulse/esp8266-oled-ssd1306" target="_blank" rel="noreferrer">there</a></p><h2 id="send-data-by-mqtt-with-advanced-lora-parameters" tabindex="-1">Send data by MQTT with advanced LoRa parameters <a class="header-anchor" href="#send-data-by-mqtt-with-advanced-lora-parameters" aria-label="Permalink to &quot;Send data by MQTT with advanced LoRa parameters&quot;">​</a></h2><ul><li>Plain text message: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoLORA -m &#39;{&quot;message&quot;:&quot;test8&quot;,&quot;txpower&quot;:17}&#39;</code><br> will make LoRa use the a txpower of 17 when sending the message &quot;test8&quot;</li><li>Binary message: <code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoLORA&quot; -m &#39;{&quot;hex&quot;:&quot;01C0FFEE&quot;}&#39;</code><br> will send binary 0x01C0FFEE</li><li>WiPhone message: <code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoLORA&quot; -m &#39;{&quot;message&quot;:&quot;test&quot;,&quot;type&quot;:&quot;WiPhone&quot;,&quot;to&quot;:&quot;123ABC&quot;,&quot;from&quot;:&quot;FFFFFF&quot;}&#39;</code><br> will send &quot;test&quot; to a WiPhone with chip ID 123ABC</li></ul><p>More info on where the LoRa library is born <a href="https://github.com/sandeepmistry/arduino-LoRa/blob/master/API.md#radio-parameters" target="_blank" rel="noreferrer">@sandeepmistry</a></p><p>Tutorial on how to leverage LoRa for a mailbox sensor from <a href="https://www.youtube.com/channel/UCz75N6inuLHXnRC5tqagNLw" target="_blank" rel="noreferrer">PricelessToolkit</a>:</p>',33),n("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/6DftaHxDawM",frameborder:"0",allow:"autoplay; encrypted-media",allowfullscreen:""},null,-1)])])}const m=s(r,[["render",p]]);export{y as __pageData,m as default};
